(* [comment removed for export] *)
Ltac notrap_fast :=
  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ exfalso;
    first [ rewrite land7_mod8 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | lia
          | let t := type of K in fail 100 "notrap: cannot refute the trap condition" t ]
  | clear K ].
(* [comment removed for export] *)
Ltac notrap_ft_fast :=
  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ clear K
  | exfalso;
    first [ rewrite land7_mod8 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | lia
          | let t := type of K in fail 100 "notrap_ft: cannot refute the trap condition" t ] ].
Local Ltac notrap ::= notrap_fast.

