Ltac nopen NSRk H x CH :=
  lazymatch type of NSRk with ANSR _ ?ns _ =>
    let nd := fresh "nd" in let L := fresh "L" in
    mnode ns x nd L H; mstep H L; nnode NSRk L CH; clear L
  end.

(* [comment removed for export] *)
Ltac mload NSRk G x :=
  lazymatch type of NSRk with ANSR _ ?ns _ =>
    let nd := fresh "nd" in let L := fresh "L" in let CH := fresh "CH" in
    mnode ns x nd L G;
    first [ rewrite (get_parent_eq _ _ _ L) in G | rewrite (get_left_eq _ _ _ L) in G | rewrite (get_right_eq _ _ _ L) in G ];
    injection G as G; nnode NSRk L CH; step; clear CH; rewrite G in *; clear L
  end.

