(* [comment removed for export] *)
Ltac nal NSRk H x :=
  lazymatch type of NSRk with ANSR _ ?ns _ =>
    let nd := fresh "nd" in let L := fresh "L" in
    let WF := fresh "WF" in let IN := fresh "IN" in let OUT := fresh "OUT" in let P := fresh "P" in
    let O1 := fresh "NZ" in let O2 := fresh "TOP" in let O3 := fresh "AL" in
    mnode ns x nd L H;
    destruct (ANSR_node _ _ _ _ _ NSRk L) as (WF & IN & OUT & P);
    unfold AIMG_TOP in OUT; destruct OUT as (O1 & O2 & O3);
    clear WF P L; clear nd
  end.
(* [comment removed for export] *)
Ltac nal_in NSRk INx :=
