Definition rebal_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ns' : NS) (lo : Z) (X : list Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (ibW lo (bv_unsigned sp) X) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ ANSR m' ns' X /\ ACONST m'.

Definition P_B_ROTL_NPF : Z := 0xbe7e8.   (* [comment removed for export] *)
Definition P_B_ROTR_NPF : Z := 0xbe9e4.   (* [comment removed for export] *)
Definition P_B_ROTL     : Z := 0xbeab4.   (* [comment removed for export] *)
Definition P_B_ROTR     : Z := 0xbe8b8.   (* [comment removed for export] *)
Definition NPF_STACK : Z := 16.
Definition ROT_STACK : Z := 80 + NPF_STACK.

(* [comment removed for export] *)
Definition rotlnpf_stmt : Prop := forall (p pr : Z) (ns ns' : NS) (lo : Z) (X : list Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ANSR m ns X ->
  rb_rot_left_npf ns p pr = Some ns' ->
  stk bsegs m lo (bv_unsigned sp) -> aceil <= lo -> lo + NPF_STACK <= bv_unsigned sp ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (rebal_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns' lo X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz p) (wz pr) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_ROTL_NPF) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Ltac rot_pre sp m lo X AC :=
  let SPR := fresh "SPR" in
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  let AF1 := fresh "AF1" in let AF2 := fresh "AF2" in let AF3 := fresh "AF3" in
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  let MU := fresh "MU" in let WM := fresh "WM" in let MUf := fresh "MUf" in
  pose proof (munch_refl (ibW lo (bv_unsigned sp) X) m) as MU; pose proof (wmono_refl bsegs m) as WM;
  pose proof (munch_refl [(lo, bv_unsigned sp)] m) as MUf;
  let G1 := fresh "G1" in let G2 := fresh "G2" in
  pose proof (ACONST_shbase _ AC) as [G1 G2]; unfold AGOT_SHBASE, ASHBASE_CELL, wz in G1, G2; rewrite ASHADOW_BASE_val in G2.
